MovingForward.XY:
var x_s := ((PixelColumn/Scan.Columns)-0.5) * Scan.Size.X;
var y_s := ((PixelRow)/Scan.Rows-0.5) * Scan.Size.Y;

var x := x_s + Scan.Center.X;
var y := y_s + Scan.Center.Y;

var xCor := Px[0] + Px[1] * x + Px[2] * x^2 + Px[3] * x^3;
xCor := clamp(0, xCor, xMax);
var yCor := y;

if (abs(UnaveragedX-xCor)<0.01 and abs(UnaveragedY-yCor)< 0.01)
    nextPx := true;

return [xCor, yCor];

MovingForward.RowColumnDepth:
var col := PixelColumn;
if (nextPx){
    nextPx := false;
    col := PixelColumn+1;
}
if (col >= Scan.Columns)
    Scan.MovingBackward();
return [PixelRow,col,PixelDepth];

MovingBackward.XY:
var x_s := ((PixelColumn)/Scan.Columns-0.5) * Scan.Size.X;
var y_s := ((PixelRow)/Scan.Rows-0.5) * Scan.Size.Y;

var x := x_s + Scan.Center.X;
var y := y_s + Scan.Center.Y;

var xCor := Px[0] + Px[1] * x + Px[2] * x^2 + Px[3] * x^3;
xCor := clamp(0, xCor, xMax);
var yCor := y;

if (abs(UnaveragedX-xCor)<0.01 and abs(UnaveragedY-yCor)< 0.01)
    nextPx := true;

return [xCor, yCor];

MovingBackward.RowColumnDepth:
var col := PixelColumn;
if (nextPx){
    nextPx := false;
    col := PixelColumn-1;
}
if (col <= 0)
    Scan.MovingNextRow();
return [PixelRow,col,PixelDepth];

MovingNextRow.XY:
var x_s := -0.5 * Scan.Size.X;
var y_s := ((PixelRow)/Scan.Rows-0.5) * Scan.Size.Y;

var x := x_s + Scan.Center.X;
var y := y_s + Scan.Center.Y;

var xCor := Px[0] + Px[1] * x + Px[2] * x^2 + Px[3] * x^3;
xCor := clamp(0, xCor, xMax);
var yCor := y;

if (abs(UnaveragedX-xCor)<0.01 and abs(UnaveragedY-yCor)< 0.01)
    nextPx := true;

return [xCor,yCor];

MovingNextRow.RowColumnDepth:
var row := PixelRow;
var col := 0;
if (nextPx){
    nextPx := false;
    row := PixelRow + 1;
    (row >= Scan.Rows) ?  Scan.End() : Scan.MovingForward();
}
return [row,col,PixelDepth];
